import {describeBounds,demSamples,resampleDEM} from './geo.js';
export function tileName(lat,lon){const y=Math.floor(lat),x=Math.floor(lon);return `Copernicus_DSM_COG_10_${y<0?'S':'N'}${String(Math.abs(y)).padStart(2,'0')}_00_${x<0?'W':'E'}${String(Math.abs(x)).padStart(3,'0')}_00_DEM`}
export function pixelPosition(image,x,y){const [ox,oy]=image.getOrigin(),[sx,sy]=image.getResolution(),offset=image.getGeoKeys().GTRasterTypeGeoKey===2?0:.5;if(!Number.isFinite(sx)||!Number.isFinite(sy)||sx<=0||sy>=0||image.fileDirectory.ModelTransformation)throw Error('僅支援北向上、未旋轉的高程圖幅');return [(x-ox)/sx-offset,(y-oy)/sy-offset]}
export function interpolateRaster(a,w,h,x,y,nodata){x=Math.max(0,Math.min(w-1,x));y=Math.max(0,Math.min(h-1,y));const i=Math.floor(x),j=Math.floor(y),ii=Math.min(w-1,i+1),jj=Math.min(h-1,j+1),u=x-i,v=y-j;let z=0;for(const [k,weight] of [[j*w+i,(1-u)*(1-v)],[j*w+ii,u*(1-v)],[jj*w+i,(1-u)*v],[jj*w+ii,u*v]]){if(weight<1e-12)continue;const q=a[k];if(!Number.isFinite(q)||q===nodata||q< -12000||q>10000)throw Error('範圍含缺值或非公尺高程，請縮小範圍或更換資料');z+=q*weight}return z}
async function readPoints(image,points,signal){const W=image.getWidth(),H=image.getHeight(),pixels=points.map(p=>pixelPosition(image,p.x,p.y));const xs=pixels.map(p=>Math.max(0,Math.min(W-1,p[0]))),ys=pixels.map(p=>Math.max(0,Math.min(H-1,p[1])));const left=Math.floor(Math.min(...xs)),top=Math.floor(Math.min(...ys)),right=Math.min(W,Math.ceil(Math.max(...xs))+2),bottom=Math.min(H,Math.ceil(Math.max(...ys))+2);if((right-left)*(bottom-top)>16e6)throw Error('圖幅過大，請先裁切到基地範圍');const raster=await image.readRasters({window:[left,top,right,bottom],samples:[0],interleave:true,signal});return pixels.map(([x,y])=>interpolateRaster(raster,right-left,bottom-top,x-left,y-top,image.getGDALNoData()))}
async function cop30URL(name,signal){
 const item=await fetch('https://planetarycomputer.microsoft.com/api/stac/v1/collections/cop-dem-glo-30/items/'+name,{signal});if(!item.ok)throw Error('30 m 圖幅未提供或服務暫時無法使用');const asset=(await item.json()).assets?.data?.href;if(!asset||new URL(asset).hostname!=='elevationeuwest.blob.core.windows.net')throw Error('高程圖幅來源不符');
 const response=await fetch('https://planetarycomputer.microsoft.com/api/sas/v1/sign?href='+encodeURIComponent(asset),{signal});if(!response.ok)throw Error('高程圖幅暫時無法授權讀取');const signed=await response.json();if(!signed.href||new URL(signed.href).hostname!=='elevationeuwest.blob.core.windows.net')throw Error('高程圖幅連結無效');return signed.href;
}
export async function fetchCop30(b,n,{signal,onProgress=()=>{},fromUrl=globalThis.GeoTIFF?.fromUrl,resolveURL=cop30URL}={}){
 if(!fromUrl)throw Error('GeoTIFF 讀取元件未載入');const d=describeBounds(b),groups=new Map(),g=new Array((n+1)**2);
 for(let j=0;j<=n;j++)for(let i=0;i<=n;i++){const lat=b.south+(b.north-b.south)*j/n,lon=b.west+(b.east-b.west)*i/n,name=tileName(lat,lon);if(!groups.has(name))groups.set(name,[]);groups.get(name).push({x:lon,y:lat,k:j*(n+1)+i})}
 if(groups.size>8)throw Error('跨越圖幅過多，請縮小範圍');let count=0;
 for(const [name,points] of groups){signal?.throwIfAborted();onProgress(`讀取 30 m 高程圖幅 ${++count} / ${groups.size}`);const tiff=await fromUrl(await resolveURL(name,signal),{allowFullFile:false,blockSize:65536,cacheSize:32},signal);try{const image=await tiff.getImage();const z=await readPoints(image,points,signal);points.forEach((p,i)=>g[p.k]=z[i])}finally{await tiff.close()}}
 if(!g.every(Number.isFinite))throw Error('高程圖幅不完整');return {...d,g,resolution:30,source:'Copernicus GLO-30 DSM',reference:{bounds:b,source:'Copernicus GLO-30 / Microsoft Planetary Computer',resolution:30,type:'DSM',tiles:[...groups.keys()]}};
}
export async function fetchMeteo(b,n,{signal,onProgress=()=>{}}={}){const q=demSamples(b),values=[];for(let offset=0;offset<q.points.length;offset+=100){signal?.throwIfAborted();const batch=q.points.slice(offset,offset+100);onProgress(`讀取 90 m 高程 ${offset} / ${q.points.length}`);const u='https://api.open-meteo.com/v1/elevation?latitude='+batch.map(p=>p.lat.toFixed(6)).join(',')+'&longitude='+batch.map(p=>p.lon.toFixed(6)).join(',');const res=await fetch(u,{signal});if(!res.ok)throw Error('高程服務回應 '+res.status);const data=await res.json();if(!Array.isArray(data.elevation)||data.elevation.length!==batch.length||!data.elevation.every(Number.isFinite))throw Error('高程回傳不完整');values.push(...data.elevation)}return {...q,g:resampleDEM(values,q.nx,q.ny,n),resolution:90,source:'Open-Meteo / Copernicus GLO-90 DSM',reference:{bounds:b,source:'Open-Meteo Copernicus GLO-90 2021',resolution:90,samples:[q.nx,q.ny],type:'DSM'}}}
export async function importGeoTIFF(file,n){
 if(file.size>150e6)throw Error('GeoTIFF 請小於 150 MB，請先裁切基地範圍');const t=await GeoTIFF.fromBlob(file);try{const im=await t.getImage(),keys=im.getGeoKeys(),epsg=keys.ProjectedCSTypeGeoKey||keys.GeographicTypeGeoKey,W=im.getWidth(),H=im.getHeight();if(W<2||H<2||im.getSamplesPerPixel()!==1)throw Error('請匯入單波段高程 GeoTIFF，不能使用衛星照片');const [ox,oy]=im.getOrigin(),[sx,sy]=im.getResolution(),offset=keys.GTRasterTypeGeoKey===2?0:.5;pixelPosition(im,ox,oy);const west=ox+offset*sx,north=oy+offset*sy,east=west+(W-1)*sx,south=north+(H-1)*sy;let w,h;
 if(epsg===4326){({w,h}=describeBounds({west,east,south,north}))}else if([3825,3826].includes(epsg)||epsg>=32601&&epsg<=32660||epsg>=32701&&epsg<=32760){w=east-west;h=north-south}else throw Error('請轉換為 TWD97 / TM2、WGS84 UTM 或 EPSG:4326 後匯入');
 if(w<=0||h<=0||w>10000||h>10000)throw Error('請先裁切成寬長 10 km 內的基地');const points=[];for(let j=0;j<=n;j++)for(let i=0;i<=n;i++)points.push({x:west+(east-west)*i/n,y:south+(north-south)*j/n});const g=await readPoints(im,points);return {w,h,g,source:'GeoTIFF · '+file.name,reference:{epsg,source:file.name,bounds:[west,south,east,north],pixelScale:[sx,sy],type:'使用者匯入高程，請確認 DTM / DSM 與公尺單位'},origin:[west,south]};}finally{await t.close()}
}
